        [HttpPost]
        public ActionResult state_tracker(string statename, string year, string month)
        {
            if (Session["UserId"] != null)
            {
                try
                {

                    if (statename != "All")
                    {
                        var ss = statename;

                        string[] states = { ss };
                        List<all_module_report> all_data = new List<all_module_report>();
                        foreach (var item in states)
                        {
                            all_module_report data = new all_module_report();

                            string state = item;
                            List<abhy_mis_awp_form> total_target = new List<abhy_mis_awp_form>();
                            List<current_events> noofcurrent = new List<current_events>();
                            List<events_material> noofupload = new List<events_material>();

                            if (year != "0" && year != "" && year != null && month != "0" && month != "" && month != null)
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == year && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.year == year && x.month == month && x.Nodal_officer == "State Level Nodal Officer").ToList();

                            }
                            else if (year != "0" && year != "" && year != null)
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == year && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.year == year && x.Nodal_officer == "State Level Nodal Officer").ToList();

                            }
                            else
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == "2024-25" && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.Nodal_officer == "State Level Nodal Officer").ToList();

                            }
                            var tt = total_target.Sum(x =>
                            {
                                if (double.TryParse(x.awp_physical_year_20_21, out double areaValue))
                                {
                                    return areaValue;
                                }
                                else
                                {
                                    return 0.0; // Default value if conversion fails
                                }
                            });
                            int noofupload_count = 0;
                            foreach (var count_upload in noofcurrent)
                            {
                                int id = Convert.ToInt32(count_upload.id);
                                var aa = ABE.obj_current_events.Where(x => x.id == id).FirstOrDefault();
                                if (aa != null && !string.IsNullOrEmpty(aa.filename))
                                {
                                    string[] count = aa.filename.Split(',');
                                    int ac = count.Length - 1; // Count the number of items in the array
                                    noofupload_count += ac; // Add the count to the total
                                }
                            }



                            data.statename = state;
                            data.demand_cost = Convert.ToDouble(noofcurrent.Count());
                            data.supply_cost = Convert.ToDouble(noofupload_count);
                            data.other_cost = Convert.ToDouble(tt);



                            all_data.Add(data);
                        }




                        var jsonResult = Json(all_data, JsonRequestBehavior.AllowGet);
                        jsonResult.MaxJsonLength = int.MaxValue;
                        return jsonResult;
                    }
                    else
                    {

                        string[] states = { "Gujarat_24", "Haryana_6", "Karnataka_29", "Madhya Pradesh_23", "Maharashtra_27", "Rajasthan_8", "Uttar Pradesh_9" };

                        List<all_module_report> all_data = new List<all_module_report>();


                        foreach (var item in states)
                        {
                            all_module_report data = new all_module_report();

                            string state = item;
                            List<abhy_mis_awp_form> total_target = new List<abhy_mis_awp_form>();
                            List<current_events> noofcurrent = new List<current_events>();
                            List<events_material> noofupload = new List<events_material>();

                            if (year != "0" && year != "" && year != null && month != "0" && month != "" && month != null)
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == year && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.year == year && x.month == month && x.Nodal_officer == "State Level Nodal Officer").ToList();
                                noofupload = ABE.obj_events_material.Where(x => x.level_event == state && x.year == year && x.month == month && x.Nodal_officer == "State Level Nodal Officer").ToList();
                            }
                            else if (year != "0" && year != "" && year != null)
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == year && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.year == year && x.Nodal_officer == "State Level Nodal Officer").ToList();
                                noofupload = ABE.obj_events_material.Where(x => x.level_event == state && x.year == year && x.Nodal_officer == "State Level Nodal Officer").ToList();
                            }
                            else
                            {
                                total_target = ABE.obj_abhy_mis_awp_form.Where(x => x.state_name == state && x.awp_fin_year == "2024-25" && x.awp_item_code == "A5.1.01").ToList();
                                noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.Nodal_officer == "State Level Nodal Officer").ToList();
                                noofupload = ABE.obj_events_material.Where(x => x.level_event == state && x.Nodal_officer == "State Level Nodal Officer").ToList();
                            }

                            var tt = total_target.Sum(x =>
                            {
                                if (double.TryParse(x.awp_physical_year_20_21, out double areaValue))
                                {
                                    return areaValue;
                                }
                                else
                                {
                                    return 0.0; // Default value if conversion fails
                                }
                            });
                            int noofupload_count = 0;
                            foreach (var count_upload in noofcurrent)
                            {
                                int id = Convert.ToInt32(count_upload.id);
                                var aa = ABE.obj_current_events.Where(x => x.id == id).FirstOrDefault();
                                if (aa != null && !string.IsNullOrEmpty(aa.filename))
                                {
                                    string[] count = aa.filename.Split(',');
                                    int ac = count.Length - 1; // Count the number of items in the array
                                    noofupload_count += ac; // Add the count to the total
                                }
                            }




                            data.statename = state;
                            data.demand_cost = Convert.ToDouble(noofcurrent.Count());
                            data.supply_cost = Convert.ToDouble(noofupload_count);
                            data.other_cost = Convert.ToDouble(tt);

                            all_data.Add(data);
                        }


                        var jsonResult = Json(all_data, JsonRequestBehavior.AllowGet);
                        jsonResult.MaxJsonLength = int.MaxValue;
                        return jsonResult;
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }

            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }


        }

        [HttpPost]
        public ActionResult district_tracker(string statename, string districtname, string year, string month)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    if (statename == "All")
                    {
                        districtname = "0";
                    }

                    if (statename != "All" && districtname != "All" && districtname != "0")
                    {
                        var ss = statename;

                        string[] states = { ss };
                        List<training_report_class> all_data = new List<training_report_class>();
                        List<abhy_mis_awp_form> total_target = new List<abhy_mis_awp_form>();
                        List<current_events> noofcurrent = new List<current_events>();
                        List<events_material> noofupload = new List<events_material>();
                        foreach (var item in states)
                        {


                            string state = item;
                            string[] dist = { districtname };
                            //var dist = districtname;


                            foreach (var item_dist in dist)
                            {
                                training_report_class data = new training_report_class();
