                                    noofcurrent = ABE.obj_current_events.Where(x => x.level_event == state && x.district == district && x.Nodal_officer == "District Level Nodal Officer").ToList();
                                    noofupload = ABE.obj_events_material.Where(x => x.level_event == state && x.district == district && x.Nodal_officer == "District Level Nodal Officer").ToList();
                                }

                                var tt = total_target.Sum(x =>
