        private int GetYearFromFinancialYear(string FinancialYear)
        {
            int FnYear = 0;
            switch (FinancialYear)
            {
                case "2021-22":
                    return FnYear = 2021;
                case "2022-23":
                    return FnYear = 2022;
                case "2023-24":
                    return FnYear = 2023;
                case "2024-25":
                    return FnYear = 2024;
            }
            return FnYear;
        }
        private int Get_Month_Number(int month)
        {
            int month_num = 0;
            switch (month)
            {
                case 4:
                    month_num = 1;
                    break;
                case 5:
                    month_num = 2;
                    break;
                case 6:
                    month_num = 3;
                    break;
                case 7:
                    month_num = 4;
                    break;
                case 8:
                    month_num = 5;
                    break;
                case 9:
                    month_num = 6;
                    break;
                case 10:
                    month_num = 7;
                    break;
                case 11:
                    month_num = 8;
                    break;
                case 12:
                    month_num = 9;
                    break;
                case 1:
                    month_num = 10;
                    break;
                case 2:
                    month_num = 11;
                    break;
                case 3:
                    month_num = 12;
                    break;
            }
            return month_num;
        }

