        [HttpPost]
        public ActionResult Save_current_event_Data(string NPMU, string current_event, string current_event1, string current_event2, string current_event3, string year, string month, string p_training_name, string type_of_event, string location_expo, string particular_expo, string event_platform, string from_date, string to_date, string reg_open_date, string reg_close_date)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    var State = "";
                    var Dist = "";
                    var Block = "";
                    var Gram = "";

                    DateTime fdt = Convert.ToDateTime(from_date);
                    DateTime tdt = Convert.ToDateTime(to_date);
                    DateTime EndDate = Convert.ToDateTime("3-31-2023");
                    DateTime StartDate = Convert.ToDateTime("4-1-2022");

                    int FnYear = GetYearFromFinancialYear(year);
                    if (FnYear == 2021)
                    {
                        if (fdt <= Convert.ToDateTime("3-31-2022") && fdt >= Convert.ToDateTime("4-1-2021"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2022)
                    {
                        if (fdt <= EndDate && fdt >= StartDate)
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2023)
                    {
                        if (fdt <= Convert.ToDateTime("3-31-2024") && fdt >= Convert.ToDateTime("4-1-2023"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2024)
                    {
                        if (fdt <= Convert.ToDateTime("3-31-2025") && fdt >= Convert.ToDateTime("4-1-2024"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    if (FnYear == 2021)
                    {
                        if (tdt <= Convert.ToDateTime("3-31-2022") && tdt >= Convert.ToDateTime("4-1-2021"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2022)
                    {
                        if (tdt <= EndDate && tdt >= StartDate)
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2023)
                    {
                        if (tdt <= Convert.ToDateTime("3-31-2024") && tdt >= Convert.ToDateTime("4-1-2023"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else if (FnYear == 2024)
                    {
                        if (tdt <= Convert.ToDateTime("3-31-2025") && tdt >= Convert.ToDateTime("4-1-2024"))
                        {

                        }
                        else
                        {
                            return Json("select valid Date or Financial year", JsonRequestBehavior.AllowGet);
                        }
                    }

                    var Email = Session["Email"].ToString();
                    var officer = Session["Officer"].ToString();

                    var userid = Convert.ToInt32(Session["UserId"]);

                    if (officer == "State Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                    }
                    if (officer == "District Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                    }
                    if (officer == "Block Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                        Block = Session["gblock"].ToString();
                    }
                    if (officer == "Gram Panchyat Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                        Block = Session["gblock"].ToString();
                        Gram = Session["ggram"].ToString();
                    }
                    var Data = new current_events();
                    if (officer == "Admin" || officer == "National Level Nodal Officer")
                    {
                        Data.level_event = NPMU;
                        Data.district = Dist;
                        Data.block = Block;
                        Data.gp = Gram;
                        var ddetails = ABE.obj_current_events.Where(x => x.level_event == NPMU && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();

                        if (ddetails.Count == 0)
                        {

                        }
                        else { return Json("Topic of Training is Already Exists. Create the Topic of Training with Different Name ", JsonRequestBehavior.AllowGet); }

                    }
                    else
                    {

                        Data.level_event = State;
                        Data.district = Dist;
                        Data.block = Block;
                        Data.gp = Gram;

                        List<current_events> ddetails = new List<current_events>();
                        if (officer == "State Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.level_event == State && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                        }
                        else if (officer == "District Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.district == Dist && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                        }
                        else if (officer == "Block Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.block == Block && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                        }
                        else if (officer == "Gram Panchyat Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.gp == Gram && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                        }

                        if (ddetails.Count == 0)
                        {

                        }
                        else { return Json("Topic of Training is Already Exists. Create the Topic of Training with Different Name ", JsonRequestBehavior.AllowGet); }


                    }
                    Data.p_training_name = p_training_name;
                    Data.type_of_event = type_of_event;
                    Data.location_expo = location_expo;
                    Data.particular_expo = particular_expo;
                    string Code = DateTime.Now.Ticks.ToString();
                    Data.unic_key = "CE" + Code;
                    //Data.level_event = level_event;
                    if (State == "0")
                    {
                        State = "";
                    }

                    if (Dist == "0")
                    {
                        Dist = "";
                    }

                    if (Block == "0")
                    {
                        Block = "";
                    }
                    if (Gram == "0")
                    {
                        Gram = "";
                    }
                    if (current_event == "0")
                    {
                        current_event = "";
                    }

                    if (current_event1 == "0")
                    {
                        current_event1 = "";
                    }

                    if (current_event2 == "0")
                    {
                        current_event2 = "";
                    }
                    if (current_event3 == "0")
                    {
                        current_event3 = "";
                    }
                    Data.userid = Convert.ToInt32(Session["UserId"]);
                    Data.year = year;
                    Data.month = month;

                    Data.event_platform = event_platform;
                    Data.from_date = from_date;
                    string monthName = month;
                    string dateString = from_date;
                    DateTime fromDate = DateTime.ParseExact(dateString, "yyyy-MM-dd", CultureInfo.InvariantCulture);
                    int monthNumber = DateTime.ParseExact(monthName, "MMMM", CultureInfo.InvariantCulture).Month;

                    if (fromDate.Month != monthNumber)
                    {
                        return Json("Choose the same month from the Select Month drop-down as the one you selected in From Date.", JsonRequestBehavior.AllowGet);
                    }

                    Data.to_date = to_date;
                    Data.reg_open_date = reg_open_date;
                    Data.reg_close_date = reg_close_date;

                    Data.Nodal_officer = officer;
                    Data.entry_by = Email;
                    ABE.obj_current_events.Add(Data);
                    ABE.SaveChanges();
                    return Json("Successfully Saved", JsonRequestBehavior.AllowGet);

                }
                catch (Exception ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);

            }

        }
