        public ActionResult current_event_Data_old(string year, string month, string date)
        {

            try
            {
                var month_num = Get_Month_Number_new(month);
                double datt = Convert.ToDouble(date);
                List<vw_current_events> ddetails = new List<vw_current_events>();
                if (year != "0" && year != "" && year != null && month_num != "0" && month_num != "" && month_num != null && date != "0" && date != "" && date != null)
                {
                    ddetails = ABE.obj_vw_current_events.Where(x => x.FinancialYear == year && x.FinancialMonth == month_num && x.day == datt).OrderByDescending(x => x.id).ToList();
                }
                else if (year != "0" && year != "" && year != null && month_num != "0" && month_num != "" && month_num != null)
                {
                    ddetails = ABE.obj_vw_current_events.Where(x => x.FinancialYear == year && x.FinancialMonth == month_num).OrderByDescending(x => x.id).ToList();
                }
