                {
                    ddetails = ABE.obj_vw_current_events.Where(x => x.FinancialYear == year).OrderByDescending(x => x.id).ToList();
                }
                else
                {
                    ddetails = ABE.obj_vw_current_events.OrderByDescending(x => x.id).ToList();
                }
                List<vw_current_events> Data = new List<vw_current_events>();
                List<vw_current_events> current_check = new List<vw_current_events>();
                foreach (var item in ddetails)
                {
                    string Nodal = item.gp;
                    if (Nodal == null)
                    {
                        Nodal = "";
                    }

                    if (Nodal != "")
                    {
                        string EventCloseDate = item.to_date;
                        DateTime currentDate = DateTime.Now;
                        string todate = currentDate.ToString("yyyy-MM-dd");
                        DateTime GDate;

                        if (DateTime.TryParseExact(EventCloseDate, "yyyy-MM-dd", null, System.Globalization.DateTimeStyles.None, out GDate))
                        {
                            DateTime toDateDateTime = DateTime.ParseExact(todate, "yyyy-MM-dd", null);

                            if (GDate >= toDateDateTime)
                            {
                                current_check.Add(item);
                            }
                        }
                    }
                    else
                    {
                        string EventCloseDate = item.to_date;
                        var Today_Date = DateTime.Now;
                        DateTime EndDate = Convert.ToDateTime(Today_Date);
                        DateTime GDate = Convert.ToDateTime(EventCloseDate);
                        TimeSpan difference = EndDate - GDate;
                        var Days = difference.Days;
                        int ddf = Convert.ToInt32(Days);

                        if (5 >= ddf)
                        {
                            current_check.Add(item);
                        }
                    }
                }


                var npmucount = current_check.Where(x => x.Nodal_officer == "National Level Nodal Officer").ToList();
                var statecount = current_check.Where(x => x.Nodal_officer == "State Level Nodal Officer").ToList();
                var distcount = current_check.Where(x => x.Nodal_officer == "District Level Nodal Officer").ToList();
                var blockcount = current_check.Where(x => x.Nodal_officer == "Block Level Nodal Officer").ToList();
                var gramcount = current_check.Where(x => x.Nodal_officer == "Gram Panchyat Nodal Officer").ToList();

                if (npmucount.Count != 0)
                {
                    foreach (var item in npmucount)
                    {
                        Data.Add(item);
                    }
                }
                if (statecount.Count != 0)
                {
                    foreach (var item in statecount)
                    {
                        Data.Add(item);
                    }
                }
                if (distcount.Count != 0)
                {
                    foreach (var item in distcount)
                    {
                        Data.Add(item);
                    }
                }
                if (blockcount.Count != 0)
                {
                    foreach (var item in blockcount)
                    {
                        Data.Add(item);
                    }
                }
                if (gramcount.Count != 0)
                {
                    foreach (var item in gramcount)
                    {
                        Data.Add(item);
                    }
                }



                var jsonResult = Json(Data, JsonRequestBehavior.AllowGet);
                jsonResult.MaxJsonLength = int.MaxValue;
                return jsonResult;

            }
            catch (Exception Ex)
            {
                return Json("Error", JsonRequestBehavior.AllowGet);
            }

