        [HttpPost]
        public ActionResult Delete_Curr_Evt_Part(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<events_calendar>(Data);
                    if (result.id != 0)
                    {
                        var nodal = Session["Officer"].ToString();
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                        var unic_key = Data1.unic_key;
                        if (Data1 != null)
                        {
                            if (Data1.Nodal_officer != "Gram Panchyat Nodal Officer")
                            {
                                var CheckData2 = ABE.obj_abhy_training_newregs.Where(x => x.unic_key == unic_key).OrderByDescending(x => x.id).ToList();
                                if (CheckData2.Count != 0)
                                {
                                    return Json("You have already registered participants for that training delete the registered participants first, and then you will be able to delete the current training.");
                                }
                                var CheckDat3 = ABE.obj_abhy_feedback_latest.Where(x => x.unic_key == unic_key).OrderByDescending(x => x.id).ToList();
                                if (CheckDat3.Count != 0)
                                {
                                    return Json("You have already feedback participant for that training, delete that training first and then you will be able to delete the current training");
                                }
                            }
                            else
                            {
                                var idddddd = result.id.ToString();
                                var d2 = ABE.obj_current_events_addnew.Where(x => x.addnewid == idddddd).ToList();
                                foreach (var item in d2)
                                {
                                    int iddd = item.id;
                                    var ddd = ABE.obj_current_events_addnew.Where(x => x.id == iddd).SingleOrDefault();
                                    ABE.Entry(ddd).State = EntityState.Deleted;
                                    ABE.SaveChanges();
                                }
                                var feedback = ABE.obj_feedback_gp.Where(x => x.feedid == idddddd).FirstOrDefault();
                                if (feedback != null) {
                                    ABE.Entry(feedback).State = EntityState.Deleted;
                                    ABE.SaveChanges();
                                }

                            }

                            ABE.Entry(Data1).State = EntityState.Deleted;
                            ABE.SaveChanges();
                            return Json("Deleted Successfully");

                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

