                        var nodal = Session["Officer"].ToString();
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                        var unic_key = Data1.unic_key;
                        var reg = ABE.obj_abhy_training_newregs.Where(x => x.unic_key == unic_key).ToList();
                        var feed = ABE.obj_abhy_feedback_latest.Where(x => x.unic_key == unic_key).ToList();
                        if (Data1 != null)
                        {
                            if (Data1.filename == null || Data1.filename == "")
                            {
                                return Json("Upload Training Material");
                            }
                            else if (reg.Count == 0)
                            {
                                return Json("Participant registration is required before submitting the training");
                            }

                            else if (feed.Count == 0)
                            {
                                return Json("Participant feedback is required before submitting the training");
                            }
                            else
                            {
                                Data1.approve_status = "Submitted";
                                Data1.reject_status = "";
                                ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                                ABE.SaveChanges();
                                return Json("Successfully Submitted");
                            }
                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        public ActionResult approvenpmu(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<events_calendar>(Data);
                    if (result.id != 0)
                    {
                        var nodal = Session["Officer"].ToString();
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                        var unic_key = Data1.unic_key;
                        var reg = ABE.obj_abhy_training_newregs.Where(x => x.unic_key == unic_key).ToList();
                        var feed = ABE.obj_abhy_feedback_latest.Where(x => x.unic_key == unic_key).ToList();
                        if (Data1 != null)
                        {
                            if (Data1.filename == null || Data1.filename == "")
                            {
                                return Json("Reject this training and asked the Concerned Person to Upload the training Material ");
                            }
                            else if (reg.Count == 0)
                            {
                                return Json("Participant registration is required before submitting the training");
                            }

                            else if (feed.Count == 0)
                            {
                                return Json("Participant feedback is required before submitting the training");
                            }
                            else
                            {
                                Data1.approve_status = "Approved";
                                Data1.reject_status = "";
                                ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                                ABE.SaveChanges();
                                return Json("Successfully Approved");
                            }
                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }
        [HttpPost]
        public ActionResult submitnpmu_gp(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<events_calendar>(Data);
                    if (result.id != 0)
                    {
                        var nodal = Session["Officer"].ToString();
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                        var total_male = Data1.male_population;
                        var total_female = Data1.female_population;
                        var total_trangender = Data1.other_population;


                        if (Data1 != null)
                        {
                            var addnewdata = ABE.obj_vw_current_events_addnew.Where(x => x.id == SocID).ToList();
                            if (Data1.atten_sheet == null || Data1.atten_sheet == "")
                            {
                                return Json("Before submitting, fill out all the required data fields and upload the training matehal.");
                            }
                            else if (addnewdata.Count != 0)
                            {
                                var addtotal_male = addnewdata.Where(x => x.gendernew == "Male").ToList().Count();
                                var addtotal_female = addnewdata.Where(x => x.gendernew == "Female").ToList().Count();
                                var addtotal_trangender = addnewdata.Where(x => x.gendernew == "Transgender").ToList().Count();
                                if (total_male != addtotal_male)
                                {
                                    return Json("The count of males does not match in the attendance sheet");
                                }
                                else if (total_female != addtotal_female)
                                {
                                    return Json("The count of Females does not match in the attendance sheet");
                                }
                                else if (total_trangender != addtotal_trangender)
                                {
                                    return Json("The count of Transgender does not match in the attendance sheet");
                                }
                                else
                                {
                                    Data1.approve_status = "Submitted";
                                    Data1.reject_status = "";
                                    ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                                    ABE.SaveChanges();
                                    return Json("Successfully Submitted");
                                }
                            }
                            else
                            {
                                return Json("Fill in the details according to the submitted attendance sheet.");
                            }

                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }
