        [HttpPost]
        public ActionResult npmureject(string id, string reject)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    if (id != null)
                    {
                        var TKID = Convert.ToInt32(id);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == TKID).SingleOrDefault();

                        if (Data1 != null)
                        {
                            Data1.approve_status = "Reject";
                            reject = reject.TrimStart(' ');
                            reject = reject.TrimEnd(' ');
                            Data1.reject_status = reject;
                            ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                            ABE.SaveChanges();
                            return Json("Rejected");

                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }

        }

        [HttpPost]
        public ActionResult Update_Curr_Part_Info(string id, string NPMU, string topic_event, string typ, string typother_one, string typother_two, /*string State, string District, string Block, */string event_platform, string fdate_d, string tdate_d, string opendate_d, string closedate_d)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    var SocID = Convert.ToInt32(id);
                    var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                    var unic_key = Data1.unic_key;
                    if (Data1 != null)
                    {
                        int asas = 0;
                        var type_of_event = Data1.type_of_event;
                        var p_training = Data1.p_training_name;
                        if (type_of_event == typ)
                        {
                            if (p_training == topic_event)
                            {
                                asas = 1;
                            }
                        }
                        Data1.id = SocID;
                        Data1.p_training_name = topic_event;
                        Data1.type_of_event = typ;
                        if (typ == "Exposure Visits")
                        {
                            event_platform = "";
                        }
                        else
                        {
                            typother_one = "";
                            typother_two = "";
                        }
                        Data1.location_expo = typother_one;
                        Data1.particular_expo = typother_two;
                        Data1.event_platform = event_platform;
                        Data1.from_date = fdate_d;
                        // int year = Convert.ToInt32(Data1.year);
                        string monthName = Data1.month;
                        string dateString = fdate_d;
                        DateTime fromDate = DateTime.ParseExact(dateString, "yyyy-MM-dd", CultureInfo.InvariantCulture);
                        int monthNumber = DateTime.ParseExact(monthName, "MMMM", CultureInfo.InvariantCulture).Month;

                        if (fromDate.Month != monthNumber)
                        {
                            return Json(" select correct from date", JsonRequestBehavior.AllowGet);
                        }
                        Data1.to_date = tdate_d;
                        Data1.reg_open_date = opendate_d;
                        Data1.reg_close_date = closedate_d;
                        List<current_events> ddetails = new List<current_events>();
                        if (Data1.Nodal_officer == "National Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.level_event == Data1.level_event && x.Nodal_officer == "National Level Nodal Officer" && x.year == Data1.year && x.month == Data1.month && x.type_of_event == typ && x.p_training_name == topic_event).OrderByDescending(x => x.id).ToList();
                        }
                        if (Data1.Nodal_officer == "State Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.level_event == Data1.level_event && x.Nodal_officer == "State Level Nodal Officer" && x.year == Data1.year && x.month == Data1.month && x.type_of_event == typ && x.p_training_name == topic_event).OrderByDescending(x => x.id).ToList();
                        }
                        if (Data1.Nodal_officer == "District Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.district == Data1.district && x.Nodal_officer == "District Level Nodal Officer" && x.year == Data1.year && x.month == Data1.month && x.type_of_event == typ && x.p_training_name == topic_event).OrderByDescending(x => x.id).ToList();
                        }
                        if (Data1.Nodal_officer == "Block Level Nodal Officer")
                        {
                            ddetails = ABE.obj_current_events.Where(x => x.block == Data1.block && x.Nodal_officer == "Block Level Nodal Officer" && x.year == Data1.year && x.month == Data1.month && x.type_of_event == typ && x.p_training_name == topic_event).OrderByDescending(x => x.id).ToList();
                        }
                        var reg_data = ABE.obj_abhy_training_newregs.Where(x => x.unic_key == unic_key).OrderByDescending(x => x.id).ToList();
                        var feed_data = ABE.obj_abhy_feedback_latest.Where(x => x.unic_key == unic_key).OrderByDescending(x => x.id).ToList();
                        if (reg_data.Count != 0)
                        {
                            return Json("You have already registered participant for that training,  delete that training first and then you will be able to update the current training");
                        }
                        if (feed_data.Count != 0)
                        {
                            return Json("Feedback have already registered for the Training.  delete the Feedback first from the Feedback Registration Table. After that, you will be able to delete that Training.");
                        }

                        if (asas != 1)
                        {
                            if (ddetails.Count != 0)
                            {
                                return Json("Topic of Training is Already Exists.  Create the Topic of Training with Different Name ", JsonRequestBehavior.AllowGet);
                            }
                        }


                        ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                        int A = ABE.SaveChanges();
                        if (A > 0)
                        {
                            return Json("Updated Successfully");
                        }
                        else
                        {
                            return Json("Not Updated");
                        }
                    }

                }
                catch (Exception ex)
                {
                    return Json("Unsuccessful Update");

                }
                return Json("Invalid");
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

