        [HttpPost]
        public ActionResult Save_event_calendar_Data(string NPMU, string current_event, string current_event1, string current_event2, string year, string month, /*string event_calendar,*/ HttpPostedFileBase download)
        {
            if (Session["UserId"] != null)
            {
                try
                {

                    var State = "";
                    var Dist = "";
                    var Block = "";

                    var Email = Session["Email"].ToString();
                    var officer = Session["Officer"].ToString();
                    int month_num = Get_Month_Number(month);
                    var userid = Convert.ToInt32(Session["UserId"]);

                    if (officer == "State Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                    }
                    if (officer == "District Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                    }
                    if (officer == "Block Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                        Block = Session["gblock"].ToString();
                    }
                    if (current_event1 == "Select District")
                    {
                        current_event1 = "";

                    }
                    if (current_event2 == "Select Block")
                    {
                        current_event2 = "";

                    }

                    var check = new events_calendar();
                    if (officer == "Admin" || officer == "National Level Nodal Officer")
                    {
                        check = ABE.obj_events_calendar.Where(x => x.current_event == NPMU && x.current_event_year == year && x.month == month).FirstOrDefault();
                    }
                    else if (officer == "State Level Nodal Officer")
                    {
                        check = ABE.obj_events_calendar.Where(x => x.current_event == State && x.current_event_year == year && x.month == month).FirstOrDefault();
                    }
                    else if (officer == "District Level Nodal Officer")
                    {
                        check = ABE.obj_events_calendar.Where(x => x.current_event == State && x.district == Dist && x.current_event_year == year && x.month == month).FirstOrDefault();
                    }
                    else if (officer == "Block Level Nodal Officer")
                    {
                        check = ABE.obj_events_calendar.Where(x => x.current_event == State && x.district == Dist && x.block == Block && x.current_event_year == year && x.month == month).FirstOrDefault();
                    }

                    if (check != null)
                    {
                        check.entry_by = Email;
                        if (check.approve_status == "Approved")
                        {
                            return Json("You have Already Enter data in this month", JsonRequestBehavior.AllowGet);
                        }
                        else if (check.approve_status == "Submitted")
                        {
                            return Json("You have Already Enter data in this month", JsonRequestBehavior.AllowGet);
                        }
                        if (download != null)
                        {
                            if (download.FileName != null)
                            {

                                String FileExt = Path.GetExtension(download.FileName).ToUpper();
                                if (FileExt != ".PDF" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".XLSM" && FileExt != ".WORD" && FileExt != ".DOC" && FileExt != ".DOCX" && FileExt != ".DOCM")
                                {
                                    return Json("Choose Valid File", JsonRequestBehavior.AllowGet);

                                }
                                string name = Path.GetFileNameWithoutExtension(download.FileName);
                                string FileName = name + DateTime.Now.Ticks + FileExt;
                                string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                                string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\calender\\");
                                if (!Directory.Exists(path))
                                {
                                    Directory.CreateDirectory(path);
                                }
                                path = path + FileName;
                                string[] count = FileName.Split('.');
                                if (count.Length != 2)
                                {
                                    return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                                }
                                download.SaveAs(path);
                                check.download_filename = FileName;
                                check.download = "/Ataljalimages/calender/" + FileName;

                            }
                        }
                        ABE.Entry(check).State = System.Data.Entity.EntityState.Modified;
                        ABE.SaveChanges();
                        return Json("Data Saved Successfully", JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        var Data = new events_calendar();
                        if (officer == "Admin" || officer == "National Level Nodal Officer")
                        {
                            Data.current_event = NPMU;
                            Data.district = Dist;
                            Data.block = Block;
                        }
                        else
                        {
                            if (current_event != "Select StateName")
                            {
                                Data.current_event = current_event;
                                Data.district = current_event1;
                                Data.block = current_event2;
                                //Data.current_event_year = current_event_year;
                            }
                            else
                            {
                                Data.current_event = State;
                                Data.district = Dist;
                                Data.block = Block;
                            }
                        }

                        if (current_event == "0")
                        {
                            current_event = "";
                        }

                        if (current_event1 == "0")
                        {
                            current_event1 = "";
                        }

                        if (current_event2 == "0")
                        {
                            current_event2 = "";
                        }
                        Data.userid = Convert.ToInt32(Session["UserId"]);

                        Data.current_event_year = year;
                        Data.month = month;
                        Data.month_number = month_num;
                        //Data.event_calendar = event_calendar;
                        Data.Nodal_officer = officer;
                        Data.entry_by = Email;
                        if (download != null)
                        {

                            if (download.FileName != null)
                            {
                                String FileExt = Path.GetExtension(download.FileName).ToUpper();
                                if (FileExt != ".PDF" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".XLSM" && FileExt != ".WORD" && FileExt != ".DOC" && FileExt != ".DOCX" && FileExt != ".DOCM")
                                {
                                    return Json("Choose Valid File", JsonRequestBehavior.AllowGet);

                                }
                                string name = Path.GetFileNameWithoutExtension(download.FileName);
                                string FileName = name + DateTime.Now.Ticks + FileExt;
                                string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                                string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\calender\\");
                                if (!Directory.Exists(path))
                                {
                                    Directory.CreateDirectory(path);
                                }
                                path = path + FileName;
                                string[] count = FileName.Split('.');
                                if (count.Length != 2)
                                {
                                    return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                                }
                                download.SaveAs(path);
                                Data.download_filename = FileName;
                                Data.download = "/Ataljalimages/calender/" + FileName;
                            }
                        }

                        ABE.obj_events_calendar.Add(Data);
                        ABE.SaveChanges();

                        return Json("Data Saved Successfully", JsonRequestBehavior.AllowGet);
                    }


                }
                catch (Exception ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }

            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        public ActionResult Delete_Evt_Cal_Part(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<events_calendar>(Data);

                    if (result.id != 0)
                    {
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_events_calendar.Where(x => x.id == SocID).SingleOrDefault();
                        if (Data1 != null)
                        {

                            ABE.Entry(Data1).State = EntityState.Deleted;
                            ABE.SaveChanges();
                            return Json("Deleted Successfully");
