        public ActionResult Excel_NPMU_level_cal(string state_name, string year1, string month1)
        {
            var state = state_name;
            var year = year1;
            var month = month1;

            if (year == "Select Financial Year")
            {
                year = "";
            }

            if (month == "Select Month")
            {
                month = "";
            }
            List<events_calendar> TDetails = ABE.obj_events_calendar.OrderByDescending(x => x.id).ToList();

            if (state != "0" && state != "" && state != null && year != "0" && year != "" && year != null && month != "0" && month != "" && month != null)
            {
                TDetails = ABE.obj_events_calendar.Where(x => x.current_event == state && x.current_event_year == year && x.month == month).OrderByDescending(x => x.id).ToList();//total list
            }
            else if (state != "0" && state != "" && state != null && year != "0" && year != "" && year != null)
            {
                TDetails = ABE.obj_events_calendar.Where(x => x.current_event == state && x.current_event_year == year).OrderByDescending(x => x.id).ToList();//total list
            }
            else if (state != "0" && state != "" && state != null)
            {
                TDetails = ABE.obj_events_calendar.Where(x => x.current_event == state).OrderByDescending(x => x.id).ToList();//total list
            }


            using (var workbook = new XLWorkbook())
            {

                var worksheet = workbook.Worksheets.Add("Training Calender NPMU Level");
                var currentRow = 1;
                worksheet.Cell(currentRow, 1).Value = "NPMU";
                worksheet.Cell(currentRow, 2).Value = "Year";
                worksheet.Cell(currentRow, 3).Value = "Month";
                worksheet.Cell(currentRow, 4).Value = "Download Training Calander";
                worksheet.Cell(currentRow, 5).Value = "Data Validation";
                worksheet.Cell(currentRow, 6).Value = "Reject Remark";

                if (TDetails.Count != 0)
                {

                    foreach (var user in TDetails)
                    {
                        currentRow++;
                        var approve_status = user.approve_status;
                        if (approve_status == "Approved")
                        {
                            approve_status = "Approved";
                        }
                        else if (approve_status == "Submitted")
                        {
                            approve_status = "Submitted";
                        }
                        else if (approve_status == "Reject")
                        {
                            approve_status = "Rejected";
                        }
                        else
                        {
                            approve_status = "Pending for Submission";
                        }
                        var reject_status = user.reject_status;
                        if (reject_status == null)
                        {
                            reject_status = "";
                        }
                        worksheet.Cell(currentRow, 1).Value = user.current_event;
                        worksheet.Cell(currentRow, 2).Value = user.current_event_year;
                        worksheet.Cell(currentRow, 3).Value = user.month;
                        worksheet.Cell(currentRow, 4).Value = user.download_filename;
                        worksheet.Cell(currentRow, 5).Value = approve_status;
                        worksheet.Cell(currentRow, 6).Value = reject_status;
                    }
                }
                else
                {
                    currentRow++;
                    worksheet.Cell(currentRow, 1).Value = "";
                    worksheet.Cell(currentRow, 2).Value = "";
                    worksheet.Cell(currentRow, 3).Value = "No Data";
                    worksheet.Cell(currentRow, 4).Value = "";
                    worksheet.Cell(currentRow, 5).Value = "";
                    worksheet.Cell(currentRow, 6).Value = "";
                }
                using (var stream = new MemoryStream())
                {
                    workbook.SaveAs(stream);
                    var content = stream.ToArray();

                    return File(
                        content,
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        "Training Calender NPMU Level.csv");
                }
            }
        }

