                    dataRow["Total Number of Participants"] = user.total_participants;
                    dataRow["SC"] = user.SC;
                    dataRow["ST"] = user.ST;
                    dataRow["OBC"] = user.OBC;
                    dataRow["General"] = user.General;
                    dataRow["Upload attendance sheet of the participants"] = user.atten_sheet_filename;
                    dataRow["Upload Photograph of the training"] = user.photograph_filename;
                    dataRow["Common Feedback from Participants on prescribed format"] = user.feedback_filename;
                    dataRow["Upload Event Content"] = user.event_upload_filename;
                    dataRow["Approve Status"] = approve;

                    dt.Rows.Add(dataRow);

                }
            }
            else
            {
                DataRow dataRow = dt.NewRow();
                dataRow["State"] = "";
                dataRow["District"] = "";
                dataRow["Block"] = "";
                dataRow["GP"] = "";
                dataRow["Year"] = "";
                dataRow["Month"] = "";
                dataRow["Type of Event"] = "";
                dataRow["Topic of Training"] = "";
                dataRow["Location"] = "";
                dataRow["From Date"] = "";
                dataRow["To Date"] = "";
                dataRow["Male"] = "";
                dataRow["Female"] = "No Data";
                dataRow["Transgender"] = "";
                dataRow["Total Number of Participants"] = "";
                dataRow["SC"] = "";
                dataRow["ST"] = "";
                dataRow["OBC"] = "";
                dataRow["General"] = "";
                dataRow["Upload attendance sheet of the participants"] = "";
                dataRow["Upload Photograph of the training"] = "";
                dataRow["Common Feedback from Participants on prescribed format"] = "";
                dataRow["Upload Event Content"] = "";
                dataRow["Approve Status"] = "";

                dt.Rows.Add(dataRow);
            }
            if (dt != null && dt.Rows.Count > 0)
            {
                System.Web.HttpContext.Current.Response.Clear();
                System.Web.HttpContext.Current.Response.ClearContent();
                System.Web.HttpContext.Current.Response.ClearHeaders();
                System.Web.HttpContext.Current.Response.Buffer = true;
                System.Web.HttpContext.Current.Response.ContentType = "text/csv";
                System.Web.HttpContext.Current.Response.AddHeader("Content-Disposition", "attachment;filename=GramPanchayat Training Registrations.csv");
                System.Web.HttpContext.Current.Response.ContentEncoding = System.Text.Encoding.GetEncoding("windows-1250");

                // Write the CSV header
                for (int j = 0; j < dt.Columns.Count; j++)
                {
                    System.Web.HttpContext.Current.Response.Write("\"" + dt.Columns[j].ToString() + "\"");
                    if (j < dt.Columns.Count - 1)
                        System.Web.HttpContext.Current.Response.Write(",");
                }
                System.Web.HttpContext.Current.Response.Write(Environment.NewLine);

                // Write the CSV data
                foreach (DataRow row in dt.Rows)
                {
                    for (int i = 0; i < dt.Columns.Count; i++)
                    {
                        string fieldValue = row[i].ToString();

                        // Enclose the field in double quotes and escape existing double quotes
                        System.Web.HttpContext.Current.Response.Write("\"" + fieldValue.Replace("\"", "\"\"") + "\"");

                        if (i < dt.Columns.Count - 1)
                            System.Web.HttpContext.Current.Response.Write(",");
                    }

                    System.Web.HttpContext.Current.Response.Write(Environment.NewLine);
                }

                System.Web.HttpContext.Current.Response.Flush();
                System.Web.HttpContext.Current.Response.End();
            }

            return RedirectToAction("Index");
        }

