                    dataRow["District"] = user.district_name;
                    dataRow["Block"] = user.block_name;
                    dataRow["GP"] = user.gp_name;
                    dataRow["Year"] = user.year;
                    dataRow["Month"] = user.month;
                    dataRow["Type of Event"] = user.type_of_event;
                    dataRow["Topic of Training"] = user.topic_training;
                    dataRow["Location"] = user.location;
                    dataRow["From Date"] = user.from_date;
                    dataRow["To Date"] = user.to_date;
                    dataRow["Upload attendance sheet of the participants"] = user.atten_sheet_filename;
                    dataRow["Name of Participant"] = user.participant_name;
                    dataRow["Gender"] = user.gender;
                    dataRow["Mobile no."] = user.mobile_no;
                    dataRow["Approve Status"] = user.approve_status_full;
                    dataRow["Reject Status"] = user.reject_status_full;
                    dataRow["Reject Remark"] = user.remark_status_full;

