                System.Web.HttpContext.Current.Response.ClearContent();
                System.Web.HttpContext.Current.Response.ClearHeaders();
                System.Web.HttpContext.Current.Response.Buffer = true;
                System.Web.HttpContext.Current.Response.ContentType = "text/csv";
                System.Web.HttpContext.Current.Response.AddHeader("Content-Disposition", "attachment;filename=Events Material GP Level.csv");
                System.Web.HttpContext.Current.Response.ContentEncoding = System.Text.Encoding.GetEncoding("windows-1250");

                // Write the CSV header
                for (int j = 0; j < dt.Columns.Count; j++)
                {
                    System.Web.HttpContext.Current.Response.Write("\"" + dt.Columns[j].ToString() + "\"");
                    if (j < dt.Columns.Count - 1)
                        System.Web.HttpContext.Current.Response.Write(",");
                }
                System.Web.HttpContext.Current.Response.Write(Environment.NewLine);

                // Write the CSV data
                foreach (DataRow row in dt.Rows)
                {
                    for (int i = 0; i < dt.Columns.Count; i++)
                    {
                        string fieldValue = row[i].ToString();

                        // Enclose the field in double quotes and escape existing double quotes
                        System.Web.HttpContext.Current.Response.Write("\"" + fieldValue.Replace("\"", "\"\"") + "\"");

                        if (i < dt.Columns.Count - 1)
                            System.Web.HttpContext.Current.Response.Write(",");
                    }
                    System.Web.HttpContext.Current.Response.Write(Environment.NewLine);
                }

                System.Web.HttpContext.Current.Response.Flush();
                System.Web.HttpContext.Current.Response.End();
            }

            return RedirectToAction("Index");
        }


        public ActionResult Excel_NPMU_Material_level(string state_name, string year1, string month1)
        {
            var state = state_name;
            var year = year1;
            var month = month1;
            if (year == "Select Financial Year")
            {
                year = "";
            }
            if (month == "Select Month")
            {
                month = "";
            }
            //var officer_name = "State Level Nodal Officer";
            List<events_material> TDetails = ABE.obj_events_material.OrderByDescending(x => x.id).ToList();


            if (state != "0" && state != "" && state != null && year != "0" && year != "" && year != null && month != "0" && month != "" && month != null)
            {
                TDetails = ABE.obj_events_material.Where(x => x.level_event == state && x.year == year && x.month == month).OrderByDescending(x => x.id).ToList();//total list
            }
            else if (state != "0" && state != "" && state != null && year != "0" && year != "" && year != null)
            {
                TDetails = ABE.obj_events_material.Where(x => x.level_event == state && x.year == year).OrderByDescending(x => x.id).ToList();//total list
            }
            else if (state != "0" && state != "" && state != null)
            {
                TDetails = ABE.obj_events_material.Where(x => x.level_event == state).OrderByDescending(x => x.id).ToList();//total list
            }

            DataTable dt = new DataTable();
            dt.Columns.Add("Topic of Event", typeof(string));
            dt.Columns.Add("Type of Event", typeof(string));
            dt.Columns.Add("Location of Exposure Visit", typeof(string));
            dt.Columns.Add("Particulars of Exposure Visit", typeof(string));
            dt.Columns.Add("NPMU", typeof(string));
            dt.Columns.Add("Year", typeof(string));
            dt.Columns.Add("Month", typeof(string));
            dt.Columns.Add("Event Platform", typeof(string));
            dt.Columns.Add("From Date", typeof(string));
            dt.Columns.Add("To Date", typeof(string));
            dt.Columns.Add("Upload Content/Module/PPT", typeof(string));
            dt.Columns.Add("Remark", typeof(string));

            var a = TDetails.Count;

            if (a != 0)
            {
                foreach (var user in TDetails)
                {

                    DataRow dataRow = dt.NewRow();
                    dataRow["Topic of Event"] = user.p_training_name;
                    dataRow["Type of Event"] = user.type_of_event;
                    dataRow["Location of Exposure Visit"] = user.location_expo;
                    dataRow["Particulars of Exposure Visit"] = user.particular_expo;
                    dataRow["NPMU"] = user.level_event;
                    dataRow["Year"] = user.year;
                    dataRow["Month"] = user.month;
                    dataRow["Event Platform"] = user.event_platform;
                    dataRow["From Date"] = user.from_date;
                    dataRow["To Date"] = user.to_date;
                    dataRow["Upload Content/Module/PPT"] = user.upload_content;
                    dataRow["Remark"] = user.remark;

                    dt.Rows.Add(dataRow);

                }
            }
            else
            {
                DataRow dataRow = dt.NewRow();
                dataRow["Topic of Event"] = "";
                dataRow["Type of Event"] = "";
                dataRow["Location of Exposure Visit"] = "";
                dataRow["Particulars of Exposure Visit"] = "";
                dataRow["NPMU"] = "";
                dataRow["Year"] = "";
                dataRow["Month"] = "";
                dataRow["Event Platform"] = "";
                dataRow["From Date"] = "";
                dataRow["To Date"] = "";
                dataRow["Upload Content/Module/PPT"] = "";
                dataRow["Remark"] = "";


                dt.Rows.Add(dataRow);
            }
            if (dt != null && dt.Rows.Count > 0)
            {
                System.Web.HttpContext.Current.Response.Clear();
                System.Web.HttpContext.Current.Response.ClearContent();
                System.Web.HttpContext.Current.Response.ClearHeaders();
                System.Web.HttpContext.Current.Response.Buffer = true;
                System.Web.HttpContext.Current.Response.ContentType = "text/csv";
                System.Web.HttpContext.Current.Response.AddHeader("Content-Disposition", "attachment;filename=Events Material NPMU Level.csv");
                System.Web.HttpContext.Current.Response.ContentEncoding = System.Text.Encoding.GetEncoding("windows-1250");

                // Write the CSV header
                for (int j = 0; j < dt.Columns.Count; j++)
                {
                    System.Web.HttpContext.Current.Response.Write("\"" + dt.Columns[j].ToString() + "\"");
                    if (j < dt.Columns.Count - 1)
                        System.Web.HttpContext.Current.Response.Write(",");
                }
                System.Web.HttpContext.Current.Response.Write(Environment.NewLine);

                // Write the CSV data
                foreach (DataRow row in dt.Rows)
                {
                    for (int i = 0; i < dt.Columns.Count; i++)
                    {
                        string fieldValue = row[i].ToString();

                        // Enclose the field in double quotes and escape existing double quotes
                        System.Web.HttpContext.Current.Response.Write("\"" + fieldValue.Replace("\"", "\"\"") + "\"");

                        if (i < dt.Columns.Count - 1)
                            System.Web.HttpContext.Current.Response.Write(",");
                    }
                    System.Web.HttpContext.Current.Response.Write(Environment.NewLine);
                }

                System.Web.HttpContext.Current.Response.Flush();
                System.Web.HttpContext.Current.Response.End();
            }

            return RedirectToAction("Index");

        }



        [HttpGet]
        public ActionResult event_calendar_Data(string Event_Calendar, string YEAR)
        {

            try
            {
                List<events_calendar> ddetails = new List<events_calendar>();
                List<events_calendar> ddetails_final = new List<events_calendar>();
                if (Event_Calendar == "All" && YEAR != "0" && YEAR != "" && YEAR != null)
                {
                    ddetails = ABE.obj_events_calendar.Where(X => X.current_event_year == YEAR && X.approve_status == "Approved").OrderBy(x => x.current_event).OrderByDescending(x => x.id).ToList();
                }
                else if (Event_Calendar == "All")
                {
                    ddetails = ABE.obj_events_calendar.Where(X => X.approve_status == "Approved").OrderBy(x => x.current_event).OrderByDescending(x => x.id).ToList();
                }
                else if (YEAR != "0" && YEAR != "" && YEAR != null)
                {
                    ddetails = ABE.obj_events_calendar.Where(X => X.current_event == Event_Calendar && X.current_event_year == YEAR && X.approve_status == "Approved").OrderBy(x => x.current_event).OrderByDescending(x => x.id).ToList();
                }
                else if (Event_Calendar != "0" && Event_Calendar != "" && Event_Calendar != null)
                {
                    ddetails = ABE.obj_events_calendar.Where(X => X.current_event == Event_Calendar && X.approve_status == "Approved").OrderBy(x => x.current_event).OrderByDescending(x => x.id).ToList();
                }

                var uniqueGpNames = ddetails.GroupBy(c => c.current_event).Select(g => g.Key).ToList();
                foreach (var gpName in uniqueGpNames)
                {
                    var matchedDataaa = ddetails.Where(x => x.current_event == gpName).OrderByDescending(x => x.id).ToList();
                    var uniqueGpNamesaa = matchedDataaa.GroupBy(c => c.current_event_year).Select(g => g.Key).ToList();
                    foreach (var gpNamea in uniqueGpNamesaa)
                    {
                        var matchedData = matchedDataaa.Where(x => x.current_event_year == gpNamea).OrderByDescending(x => x.id).FirstOrDefault();

                        if (matchedData != null)
                        {
                            ddetails_final.Add(matchedData);

                        }
                    }
                }
                var dd = ddetails_final.OrderBy(x => x.current_event).ToList();
                var jsonResult = Json(dd, JsonRequestBehavior.AllowGet);
                jsonResult.MaxJsonLength = int.MaxValue;
                return jsonResult; ;
            }
            catch (Exception Ex)
            {
                return Json("Error", JsonRequestBehavior.AllowGet);
            }

        }

