        [HttpPost]
        public ActionResult submittodpmu(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<current_events>(Data);

                    if (result.id != 0)
                    {
                        if (Data != null)
                        {
                            var TKID = Convert.ToInt32(result.id);
                            var Data1 = ABE.obj_current_events.Where(x => x.id == TKID).SingleOrDefault();
                            Data1.approve_status = "Submitted To DPMU";
                            Data1.reject_status = "";
                            ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                            ABE.SaveChanges();
                            return Json("Successfully Submitted");
                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }


                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }

        }

