        [HttpPost]
        public ActionResult distsubmittogp(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<current_events>(Data);

                    if (result.id != 0)
                    {
                        if (Data != null)
                        {
                            var TKID = Convert.ToInt32(result.id);
                            var Data1 = ABE.obj_current_events.Where(x => x.id == TKID).SingleOrDefault();
                            var state = Data1.level_event;
                            var dist = Data1.district;
                            var block = Data1.block;
                            var gram = Data1.gp;
                            var year = Data1.year;
                            var month = Data1.month;
                            var typeofevent = Data1.type_of_event;
                            var topicofevent = Data1.p_training_name;
                            var from_date = Data1.from_date;
                            var to_date = Data1.to_date;
                            var abc = ABE.obj_reg_traininggp.Where(x => x.state_name == state && x.district_name == dist && x.block_name == block && x.gp_name == gram && x.year == year && x.month == month && x.topic_training == topicofevent && x.type_of_event == typeofevent).OrderByDescending(x => x.id).ToList();
                            if (abc.Count == 0)
                            {
                                return Json("fill the details of the concerned event under Gram Panchayat module before submitting that created event.", JsonRequestBehavior.AllowGet);
                            }
                            else if (abc.Count == 1)
                            {
                                for (int i = 0; i < abc.Count; i++)
                                {
                                    int id = abc[i].id;
                                    var reg_data = ABE.obj_reg_traininggp.Where(x => x.id == id).SingleOrDefault();
