        [HttpPost]
        public ActionResult Reg_Gp_data_fetch(string state, string district, string block, string gram, string year, string month, string Topic_Training_New)
        {

            if (Session["UserId"] != null)
            {
                try
                {
                    var officer_name = "Gram Panchyat Nodal Officer";

                    if (state == "Select State")
                    {
                        state = "";
                    }

                    if (district == "Select District")
                    {
                        district = "";
                    }

                    if (block == "Select Block")
                    {
                        block = "";
                    }

                    if (gram == "Select GramPanchayat")
                    {
                        gram = "";
                    }

                    if (year == "Select Financial Year")
                    {

                    }

                    if (month == "Select Month")
                    {
                        month = "";
                    }
                    if (Topic_Training_New == "Select Event/Training")
                    {
                        Topic_Training_New = "";
                    }

