        [HttpGet]
        public ActionResult event_calendar_selection_state(string STATE)
        {
            try
            {
                List<events_calendar> StateList = new List<events_calendar>();
                List<events_calendar> DisList = new List<events_calendar>();
                List<events_calendar> BlockList = new List<events_calendar>();

                var details = ABE.obj_events_calendar.Where(x => x.current_event == STATE && x.district == "" && x.block == "").OrderByDescending(x => x.month_number).FirstOrDefault();
                StateList.Add(details);

                var ddetails = ABE.obj_events_calendar.Where(x => x.current_event == STATE && x.district != "").Select(x => x.district).Distinct().ToList();
                if (ddetails.Count != 0)
                {
                    for (var i = 0; i < ddetails.Count; i++)
                    {
                        string Dist = ddetails[i];
                        var ddetails1 = ABE.obj_events_calendar.Where(x => x.current_event == STATE && x.district == Dist && x.block == "").OrderByDescending(x => x.month_number).FirstOrDefault();
                        DisList.Add(ddetails1);
                        var ddetails2 = ABE.obj_events_calendar.Where(x => x.current_event == STATE && x.district == Dist && x.block != "").Select(x => x.block).Distinct().ToList();

                        for (var j = 0; j < ddetails2.Count; j++)
                        {
                            string Block = ddetails2[j];
                            var ddetails3 = ABE.obj_events_calendar.Where(x => x.current_event == STATE && x.district == Dist && x.block == Block).OrderByDescending(x => x.month_number).FirstOrDefault();
                            BlockList.Add(ddetails3);
                        }
                    }

                }
                var data = StateList.Concat(DisList).Concat(BlockList).Distinct().OrderByDescending(x => x.id).ToList();
                return Json(data, JsonRequestBehavior.AllowGet);
                //return Json(StateList + "," + DisList + "," + BlockList, JsonRequestBehavior.AllowGet);

            }
            catch (Exception Ex)
            {
                return Json("Error", JsonRequestBehavior.AllowGet);
            }

        }

