        [HttpPost]
        public ActionResult Save_event_material_Data(string p_training_name, string type_of_event, string location_expo, string particular_expo, string NPMU, string current_event, string current_event1, string current_event2, string current_event3, string year, string month, string event_platform, string from_date, string to_date, HttpPostedFileBase upload, string remark)
        {
            if (Session["UserId"] != null)
            {

                try
                {
                    var State = "";
                    var Dist = "";
                    var Block = "";
                    var Gram = "";

                    var Email = Session["Email"].ToString();
                    var officer = Session["Officer"].ToString();

                    var userid = Convert.ToInt32(Session["UserId"]);

                    if (officer == "State Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                    }
                    if (officer == "District Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                    }
                    if (officer == "Block Level Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                        Block = Session["gblock"].ToString();
                    }
                    if (officer == "Gram Panchyat Nodal Officer")
                    {
                        State = Session["gstate"].ToString();
                        Dist = Session["gdist"].ToString();
                        Block = Session["gblock"].ToString();
                        Gram = Session["ggram"].ToString();
                    }
                    var Data = new events_material();
                    if (officer == "Admin" || officer == "National Level Nodal Officer")
                    {
                        Data.level_event = NPMU;
                        Data.district = Dist;
                        Data.block = Block;
                        Data.gp = Gram;
                    }
                    else
                    {
                        Data.level_event = State;
                        Data.district = Dist;
                        Data.block = Block;
                        Data.gp = Gram;
                    }

                    Data.p_training_name = p_training_name;
                    Data.type_of_event = type_of_event;
                    Data.location_expo = location_expo;
                    Data.particular_expo = particular_expo;

                    List<current_events> ddetails = new List<current_events>();
                    if (officer == "State Level Nodal Officer")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.level_event == State && x.year == year && x.month == month && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }
                    else if (officer == "District Level Nodal Officer")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.district == Dist && x.year == year && x.month == month && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }
                    else if (officer == "Block Level Nodal Officer")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.block == Block && x.year == year && x.month == month && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }
                    else if (officer == "Gram Panchyat Nodal Officer")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.gp == Gram && x.year == year && x.month == month && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }
                    else if (officer == "National Level Nodal Officer" || officer == "Admin")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.level_event == NPMU && x.year == year && x.month == month && x.Nodal_officer == officer && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }

                    var un = ddetails[0].unic_key;
                    Data.unic_key = un;

                    if (State == "0")
                    {
                        State = "";
                    }

                    if (Dist == "0")
                    {
                        Dist = "";
                    }

                    if (Block == "0")
                    {
                        Block = "";
                    }
                    if (Gram == "0")
                    {
                        Gram = "";
                    }
                    if (current_event == "0")
                    {
                        current_event = "";
                    }

                    if (current_event1 == "0")
                    {
                        current_event1 = "";
                    }

                    if (current_event2 == "0")
                    {
                        current_event2 = "";
                    }
                    if (current_event3 == "0")
                    {
                        current_event3 = "";
                    }
                    Data.userid = Convert.ToInt32(Session["UserId"]);
                    Data.year = year;
                    Data.month = month;
                    Data.event_platform = event_platform;
                    Data.from_date = from_date;
                    Data.to_date = to_date;
                    Data.Nodal_officer = officer;
                    Data.entry_by = Email;





                    if (upload != null)
                    {

                        if (upload.FileName != null)
                        {
                            String FileExt = Path.GetExtension(upload.FileName).ToUpper();
                            if (FileExt != ".PDF" && FileExt != ".PPT" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".XLSM" && FileExt != ".WORD" && FileExt != ".DOC" && FileExt != ".DOCX" && FileExt != ".DOCM")
                            {
                                return Json("Choose Valid File", JsonRequestBehavior.AllowGet);

                            }
                            string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                            string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\");
                            path = path + upload.FileName;
                            string[] count = upload.FileName.Split('.');
                            if (count.Length != 2)
                            {
                                return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                            }
                            upload.SaveAs(path);
                            Data.upload_content = upload.FileName;
                            Data.upload_content = "/Ataljalimages/" + upload.FileName;

                        }
                    }

                    Data.remark = remark;

                    ABE.obj_events_material.Add(Data);
                    ABE.SaveChanges();

                    return Json("Data Saved Successfully", JsonRequestBehavior.AllowGet);
                }
                catch (Exception ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

