            if (Session["UserId"] != null)
            {

                try
                {
                    var Email = Session["Email"].ToString();
                    var officer = Session["Officer"].ToString();
                    var Data = new events_material();
                    Data.level_event = State;
                    Data.district = Dist;
                    Data.block = Block;
                    Data.gp = Gram;
                    Data.p_training_name = p_training_name;
                    Data.type_of_event = type_of_event;
                    Data.location_expo = location_expo;
                    Data.particular_expo = particular_expo;
                    var off = "Gram Panchyat Nodal Officer";
                    List<current_events> ddetails = new List<current_events>();
                    if (off == "Gram Panchyat Nodal Officer")
                    {
                        ddetails = ABE.obj_current_events.Where(x => x.block == Block && x.year == year && x.month == month && x.Nodal_officer == off && x.type_of_event == type_of_event && x.p_training_name == p_training_name).OrderByDescending(x => x.id).ToList();
                    }
                    var un = ddetails[0].unic_key;
                    Data.unic_key = un;
                    if (State == "0")
                    {
                        State = "";
                    }

                    if (Dist == "0")
                    {
                        Dist = "";
                    }

                    if (Block == "0")
                    {
                        Block = "";
                    }
                    if (Gram == "0")
                    {
                        Gram = "";
                    }
                    if (current_event == "0")
                    {
                        current_event = "";
                    }

                    if (current_event1 == "0")
                    {
                        current_event1 = "";
                    }

                    if (current_event2 == "0")
                    {
                        current_event2 = "";
                    }
                    if (current_event3 == "0")
                    {
                        current_event3 = "";
                    }
                    Data.userid = Convert.ToInt32(Session["UserId"]);
                    //Data.level_event = State;
                    //Data.district = Dist;
                    //Data.block = Block;
                    Data.year = year;
                    Data.month = month;
                    Data.event_platform = event_platform;
                    Data.from_date = from_date;
                    Data.to_date = to_date;
                    if (Session["Access_auth"].ToString() == "GP-Training")
                    {
                        Data.Nodal_officer = "Gram Panchyat Nodal Officer";
                    }
                    else
                    {
                        Data.Nodal_officer = officer;
                    }

                    Data.entry_by = Email;

                    if (upload != null)
                    {

                        if (upload.FileName != null)
                        {
                            String FileExt = Path.GetExtension(upload.FileName).ToUpper();
                            string name = Path.GetFileNameWithoutExtension(upload.FileName);
                            string FileName = name + DateTime.Now.Ticks + FileExt;

                            string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                            string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\GP Materials\\" + Gram + "\\");
                            if (!Directory.Exists(path))
                            {
                                Directory.CreateDirectory(path);
                            }
                            path = path + FileName;
                            string[] count = FileName.Split('.');
                            if (count.Length != 2)
                            {
                                return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                            }
                            upload.SaveAs(path);
                            Data.upload_content = FileName;
                            Data.upload_content = "/Ataljalimages/GP Materials/" + Gram + "/" + FileName;

                        }
                    }

                    Data.remark = remark;

                    ABE.obj_events_material.Add(Data);
                    ABE.SaveChanges();

                    return Json("Data Saved Successfully", JsonRequestBehavior.AllowGet);
                }
                catch (Exception ex)
                { return Json("Error", JsonRequestBehavior.AllowGet); }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }
