        {
            if (Session["UserId"] != null)
            {
                try
                {
                    if (year == "Select Financial Year")
                    {
                        year = "";
                    }
                    if (month == "Select Month")
                    {
                        month = "";
                    }
                    var officer = Session["Officer"].ToString();
                    if (officer == "Admin" || officer == "National Level Nodal Officer")
                    {
                        if (npmu != "0" && npmu != "" && npmu != null && year != "0" && year != "" && year != null && month != "0" && month != "" && month != null)
                        {
                            var ddetails = ABE.obj_events_material.Where(x => x.level_event == npmu && x.Nodal_officer == officer && x.year == year && x.month == month).OrderByDescending(x => x.id).ToList();
                            return Json(ddetails, JsonRequestBehavior.AllowGet);
                        }
                        if (npmu != "0" && npmu != "" && npmu != null && year != "0" && year != "" && year != null)
                        {
                            var ddetails = ABE.obj_events_material.Where(x => x.level_event == npmu && x.Nodal_officer == officer && x.year == year).OrderByDescending(x => x.id).ToList();
                            return Json(ddetails, JsonRequestBehavior.AllowGet);
                        }
                        if (npmu != "0" && npmu != "" && npmu != null)
                        {
                            var ddetails = ABE.obj_events_material.Where(x => x.level_event == npmu && x.Nodal_officer == officer).OrderByDescending(x => x.id).ToList();
                            return Json(ddetails, JsonRequestBehavior.AllowGet);
