        [HttpPost]
        public ActionResult Update_Material_Part_Info(string id, string NPMU, string topic_event, string typ, string typother_one, string typother_two, /*string State, string District, string Block,*/ string event_platform, string fdate_d, string tdate_d, HttpPostedFileBase file_up, string remark)
        {
            if (Session["UserId"] != null)
            {
                try
                {

                    var SocID = Convert.ToInt32(id);
                    var Data1 = ABE.obj_events_material.Where(x => x.id == SocID).SingleOrDefault();
                    if (Data1 != null)
                    {
                        Data1.id = SocID;
                        Data1.level_event = NPMU;
                        Data1.p_training_name = topic_event;
                        Data1.type_of_event = typ;
                        Data1.location_expo = typother_one;
                        Data1.particular_expo = typother_two;
                        //Data1.level_event = State;
                        //Data1.district = District;
                        //Data1.block = Block;
                        Data1.event_platform = event_platform;
                        Data1.from_date = fdate_d;
                        Data1.to_date = tdate_d;

                        if (file_up != null)
                        {
                            if (file_up.FileName != null)
                            {

                                {
                                    String FileExt = Path.GetExtension(file_up.FileName).ToUpper();
                                    if (FileExt != ".PDF" && FileExt != ".PPT" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".XLSM" && FileExt != ".WORD" && FileExt != ".DOC" && FileExt != ".DOCX" && FileExt != ".DOCM")
                                    {
                                        return Json("Choose Valid File", JsonRequestBehavior.AllowGet);

                                    }

                                    string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                                    string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\");
                                    path = path + file_up.FileName;
                                    string[] count = file_up.FileName.Split('.');
                                    if (count.Length != 2)
                                    {
                                        return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                                    }
                                    file_up.SaveAs(path);
                                    Data1.upload_content = file_up.FileName;
                                    Data1.upload_content = "/Ataljalimages/" + file_up.FileName;

                                }
                            }
                        }

                        Data1.remark = remark;

                        ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                        int A = ABE.SaveChanges();
                        if (A > 0)
                        {
                            return Json("Updated Successfully");
                        }
                        else
                        {
                            return Json("Not Updated");
                        }
                    }

                }
                catch (Exception ex)
                {
                    return Json("Unsuccessful Update");

                }
                return Json("Invalid");
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

