                                    string FileName = name + DateTime.Now.Ticks + FileExt;
                                    string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                                    string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\GPReg\\Feedback\\" + Gram + "\\");
                                    if (!Directory.Exists(path))
                                    {
                                        Directory.CreateDirectory(path);
                                    }
                                    path = path + FileName;
                                    string[] count = FileName.Split('.');
                                    if (count.Length != 2)
                                    {
                                        return Json("Common Feedback from Participants on prescribed format is Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                                    }
