                                    Data1.feedback = "/Ataljalimages/GPReg/Feedback/" + Gram + "/" + FileName;

                                }
                            }
                        }
                        if (upload_ee != null)
                        {
                            if (upload_ee.FileName != null)
                            {

                                {
                                    String FileExt = Path.GetExtension(upload_ee.FileName).ToUpper();
                                    if (FileExt != ".PDF" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".PPT" && FileExt != ".WORD" && FileExt != ".DOCX" && FileExt != ".DOC")
                                    {
                                        return Json("Upload Training Material is not Valid File", JsonRequestBehavior.AllowGet);

                                    }
                                    string name = Path.GetFileNameWithoutExtension(upload_ee.FileName);
                                    string FileName = name + DateTime.Now.Ticks + FileExt;
                                    string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                                    string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\GPReg\\event_upload\\" + Gram + "\\");
                                    if (!Directory.Exists(path))
                                    {
                                        Directory.CreateDirectory(path);
                                    }
                                    path = path + FileName;
                                    string[] count = FileName.Split('.');
                                    if (count.Length != 2)
