        [HttpPost]
        public ActionResult Participant_reg_info_Data(string Data)   //data to table
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<Pagenum>(Data);
                    List<abhy_training_newregs> ddetails = new List<abhy_training_newregs>();
                    //var ddetails = ABE.obj_abhy_training_newregs.OrderByDescending(x=>x.id).ToList();
                    var State = result.statename;
                    var Dist = result.districtname;
                    var Block = result.blockname;
                    if (Dist == "Select District")
                    {
                        Dist = "";
                    }
                    if (Block == "Select Block")
                    {
                        Block = "";
                    }
                    var PageNumber = result.PageNumber;

                    var officer = Session["Officer"].ToString();
                    if (ddetails != null)
                    {
                        if (officer == "Admin" || officer == "National Level Nodal Officer")
                        {
                            if (State == "All")
                            {
                                ddetails = ABE.obj_abhy_training_newregs.OrderByDescending(x => x.id).ToList();
                            }
                            else if (State != "0" && State != "" && State != null && Dist != "0" && Dist != "" && Dist != null && Block != "0" && Block != "" && Block != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State && x.p_district_name == Dist && x.p_block_name == Block).OrderByDescending(x => x.id).ToList();

                            }
                            else if (State != "0" && State != "" && State != null && Dist != "0" && Dist != "" && Dist != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State && x.p_district_name == Dist).OrderByDescending(x => x.id).ToList();

                            }
                            else if (State != "0" && State != "" && State != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State).OrderByDescending(x => x.id).ToList();

                            }
                        }

                        else
                        {
                            if (State != "0" && State != "" && State != null && Dist != "0" && Dist != "" && Dist != null && Block != "0" && Block != "" && Block != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State && x.p_district_name == Dist && x.p_block_name == Block).OrderByDescending(x => x.id).ToList();

                            }
                            else if (State != "0" && State != "" && State != null && Dist != "0" && Dist != "" && Dist != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State && x.p_district_name == Dist).OrderByDescending(x => x.id).ToList();

                            }
                            else if (State != "0" && State != "" && State != null)
                            {
                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.p_state_name == State).OrderByDescending(x => x.id).ToList();

                            }

                        }
                    }

                    ViewBag.Totalpages = Math.Ceiling(ddetails.Count() / 100.0);
                    Session["PageNumber"] = PageNumber;
                    ddetails = ddetails.Skip((PageNumber - 1) * 100).Take(100).OrderByDescending(x => x.id).ToList();
                    return Json(ddetails, JsonRequestBehavior.AllowGet);
                }

                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);

