        [HttpPost]
        public ActionResult state_npmu_data_report(string state, string dist, string block, string gram, string year, string month)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    DateTime now = DateTime.Now;
                    int startMonth = 4; // April 
                    int currentYear = now.Year;
                    int startYear = (now.Month >= startMonth) ? currentYear : currentYear - 1;
                    int endYear = startYear + 1;
                    string financialYear = $"{startYear}-{endYear.ToString().Substring(2)}";

                    int currentMonth = now.Month;

                    DateTimeFormatInfo dtfi = CultureInfo.CurrentCulture.DateTimeFormat;
                    List<dynamic> monthnn = new List<dynamic>();
                    if (financialYear == year)
                    {
                        if (month == "0")
                        {
                            for (int montha = startMonth; montha <= currentMonth; montha++)
                            {
                                // Handle the case where the month exceeds December
                                int actualMonth = montha > 12 ? montha - 12 : montha;
                                string monthName = dtfi.GetMonthName(actualMonth);
                                monthnn.Add(monthName);
                            }
                        }
                        else
                        {
                            string[] states = { month };
                            int[] monthNumbers = new int[states.Length];

                            for (int i = 0; i < states.Length; i++)
                            {
                                switch (states[i])
                                {
                                    case "January":
                                        monthNumbers[i] = 1;
                                        break;
                                    case "February":
                                        monthNumbers[i] = 2;
                                        break;
                                    case "March":
                                        monthNumbers[i] = 3;
                                        break;
                                    case "April":
                                        monthNumbers[i] = 4;
                                        break;
                                    case "May":
                                        monthNumbers[i] = 5;
                                        break;
                                    case "June":
                                        monthNumbers[i] = 6;
                                        break;
                                    case "July":
                                        monthNumbers[i] = 7;
                                        break;
                                    case "August":
                                        monthNumbers[i] = 8;
                                        break;
                                    case "September":
