                                }
                                if (item.female_population != null)
                                {
                                    female += item.female_population;
                                }
                                if (item.other_population != null)
                                {
                                    trangender += item.other_population;
                                }
                                if (item.total_participants != null)
                                {
                                    total += item.total_participants;
                                }
                            }

                            List<vw_current_events> ddd = new List<vw_current_events>();



                            double spmutarget = 0;
