                            {
                                foreach (var item in monthnn)
                                {
                                    var mont = item;
                                    spmucum += dd.Where(x => x.Nodal_officer == "State Level Nodal Officer" && x.month == mont).ToList().Count();
                                    dpmucum += dd.Where(x => x.Nodal_officer == "District Level Nodal Officer" && x.month == mont).ToList().Count();
                                    blockcum += dd.Where(x => x.Nodal_officer == "Block Level Nodal Officer" && x.month == mont).ToList().Count();
