                                    spmucum += dd_newa.Where(x => x.Nodal_officer == "State Level Nodal Officer" && x.month == mont).ToList().Count();
                                    dpmucum += dd_newa.Where(x => x.Nodal_officer == "District Level Nodal Officer" && x.month == mont).ToList().Count();
                                    blockcum += dd_newa.Where(x => x.Nodal_officer == "Block Level Nodal Officer" && x.month == mont).ToList().Count();
                                    gramcum += dd_newa.Where(x => x.Nodal_officer == "Gram Panchyat Nodal Officer" && x.month == mont).ToList().Count();
                                }
