                            int blockmtotal = blocklist.Where(x => x.p_gender == "Male").Count();
                            int blockftotal = blocklist.Where(x => x.p_gender == "Female").Count();
                            int blocktratotal = blocklist.Where(x => x.p_gender == "Transgender").Count();

