                            count.month = month;

                            count.spmutotaltarger = spmutarget;
                            count.spmumonthcum = spmumonthly;
                            count.spmutotalcum = spmucum;
                            count.spmucount = spmuttotal;
                            count.spmucount_male = spmumtotal;
                            count.spmucount_female = spmuftotal;
                            count.spmucount_trangender = spmutratotal;
                            int spmucount_total_count = spmumtotal + spmuftotal + spmutratotal;
                            double originalValue = Convert.ToDouble(spmuftotal);
                            double totalValue = Convert.ToDouble(spmucount_total_count);
                            double spmupercentage = 0;
                            if (spmucount_total_count != 0)
                            {
                                spmupercentage = (originalValue / totalValue) * 100;
                            }
                            count.spmucount_female_per = spmupercentage;
                            count.spmucount_total = spmucount_total_count;

                            count.dpmutotaltarger = dpmutarget;
                            count.dpmumonthcum = dpmumonthly;
                            count.dpmutotalcum = dpmucum;
                            count.dpmucount = dpmuttotal;
                            count.dpmucount_male = dpmumtotal;
                            count.dpmucount_female = dpmuftotal;
                            count.dpmucount_trangender = dpmutratotal;
                            int dpmucount_total_count = dpmumtotal + dpmuftotal + dpmutratotal;
                            double dpmuoriginalValue = Convert.ToDouble(dpmuftotal);
                            double dpmutotalValue = Convert.ToDouble(dpmucount_total_count);
                            double dpmupercentage = 0;
                            if (dpmucount_total_count != 0)
                            {
                                dpmupercentage = (dpmuoriginalValue / dpmutotalValue) * 100;
                            }
                            count.dpmucount_female_per = dpmupercentage;
                            count.dpmucount_total = dpmucount_total_count;

                            count.blocktotaltarger = blocktarget;
                            count.blockmonthcum = blockmonthly;
                            count.blocktotalcum = blockcum;
                            count.blockcount = blockttotal;
                            count.blockcount_male = blockmtotal;
                            count.blockcount_female = blockftotal;
                            count.blockcount_trangender = blocktratotal;
                            int blockcount_total_count = blockmtotal + blockftotal + blocktratotal;
                            double blockoriginalValue = Convert.ToDouble(blockftotal);
                            double blocktotalValue = Convert.ToDouble(blockcount_total_count);
                            double blockpercentage = 0;
                            if (blockcount_total_count != 0)
                            {
                                blockpercentage = (blockoriginalValue / blocktotalValue) * 100;
                            }
                            count.blockcount_female_per = blockpercentage;
                            count.blockcount_total = blockcount_total_count;

                            count.gramtotaltarger = gramtarget;
                            count.grammonthcum = grammonthly;
                            count.gramtotalcum = gramcum;
                            count.gramcount = total;
                            count.gramcount_male = male;
                            count.gramcount_female = female;
                            count.gramcount_trangender = trangender;
                            int? gramcount_total_count = total;
                            double gramoriginalValue = Convert.ToDouble(female);
                            double gramtotalValue = Convert.ToDouble(total);
                            double grampercentage = 0;
                            if (total != 0)
                            {
                                grampercentage = (gramoriginalValue / gramtotalValue) * 100;
                            }
                            if (grampercentage == 0)
                            {
                                count.gramcount_female_per = grampercentage;
                            }
                            else
                            {
                                string formatted_percentage = grampercentage.ToString("0.00");
