                    int spmuftotal = spmulist.Where(x => x.gender == "Female").Count();
                    int spmutratotal = spmulist.Where(x => x.gender == "Transgender").Count();
                    //district

                    var dpmulist = ddetails.Where(x => x.nodal_officer == "District Level Nodal Officer").ToList();
                    int dpmuttotal = dpmulist.Count();
                    int dpmumtotal = dpmulist.Where(x => x.gender == "Male").Count();
                    int dpmuftotal = dpmulist.Where(x => x.gender == "Female").Count();
                    int dpmutratotal = dpmulist.Where(x => x.gender == "Transgender").Count();
                    //block
                    var blocklist = ddetails.Where(x => x.nodal_officer == "Block Level Nodal Officer").ToList();
                    int blockttotal = blocklist.Count();
                    int blockmtotal = blocklist.Where(x => x.gender == "Male").Count();
                    int blockftotal = blocklist.Where(x => x.gender == "Female").Count();
                    int blocktratotal = blocklist.Where(x => x.gender == "Transgender").Count();



                    int tot = npmuttotal + spmuttotal + dpmuttotal + blockttotal;

                    count.sta = sta;
                    count.dis = dis;
                    count.blo = blo;
                    count.npmu = npmu;

                    count.count = fintotal;
                    count.totalcount = tot;

                    count.npmucount = npmuttotal;
                    count.npmucount_male = npmumtotal;
                    count.npmucount_female = npmuftotal;
                    count.npmucount_trangender = npmutratotal;

                    count.spmucount = spmuttotal;
                    count.spmucount_male = spmumtotal;
                    count.spmucount_female = spmuftotal;
                    count.spmucount_trangender = spmutratotal;

                    count.dpmucount = dpmuttotal;
                    count.dpmucount_male = dpmumtotal;
                    count.dpmucount_female = dpmuftotal;
                    count.dpmucount_trangender = dpmutratotal;

                    count.blockcount = blockttotal;
                    count.blockcount_male = blockmtotal;
                    count.blockcount_female = blockftotal;
                    count.blockcount_trangender = blocktratotal;

                    var jsonresult = Json(count, JsonRequestBehavior.AllowGet);
                    jsonresult.MaxJsonLength = int.MaxValue;
                    return jsonresult;
                    //return Json(social_count + "," + Totalpagessocial, JsonRequestBehavior.AllowGet);

                }

                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }

            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);

            }

        }

