                                ddetails = ABE.obj_abhy_training_newregs.Where(x => x.typeofevent == event_name && x.p_state_name == State && x.nodal == "State Level Nodal Officer").OrderByDescending(x => x.id).ToList();//total list

                            }
                        }
                    }

                    List<vw_current_events> ddd = new List<vw_current_events>();
                    int aa = 0;
                    if (State == "All")
                    {
                        var date = DateTime.Now.ToString("yyyy-MM-dd");
                        DateTime dd = Convert.ToDateTime(date);
                        foreach (var item in current)
                        {
                            var todate = item.to_date;
                            DateTime tt = Convert.ToDateTime(todate);
                            if (tt <= dd)
                            {
                                ddd.Add(item);
                            }

                        }
                    }
                    else
                    {
                        var date = DateTime.Now.ToString("yyyy-MM-dd");
                        DateTime dd = Convert.ToDateTime(date);
                        foreach (var item in current)
                        {
                            var todate = item.to_date;
                            DateTime tt = Convert.ToDateTime(todate);
                            if (tt <= dd)
                            {
                                ++aa;
                            }
                        }
                    }
                    int fintotal = aa;
                    //Total
                    int ttotal = 0;
                    int mtotal = 0;
                    int ftotal = 0;
                    int tratotal = 0;

                    int sta = 0;
                    int dis = 0;
                    int blo = 0;
                    int npmu = 0;

                    if (State == "All")
                    {
                        var ddlist = ABE.obj_abhy_training_newregs.OrderByDescending(x => x.id).ToList();//total list
                        ttotal = ddlist.Count();
                        mtotal = ddlist.Where(x => x.p_gender == "Male").Count();
                        ftotal = ddlist.Where(x => x.p_gender == "Female").Count();
                        tratotal = ddlist.Where(x => x.p_gender == "Transgender").Count();

                        npmu = ddd.Where(x => x.Nodal_officer == "National Level Nodal Officer").Count();
                        sta = ddd.Where(x => x.Nodal_officer == "State Level Nodal Officer").Count();
                        dis = ddd.Where(x => x.Nodal_officer == "District Level Nodal Officer").Count();
                        blo = ddd.Where(x => x.Nodal_officer == "Block Level Nodal Officer").Count();
                    }
                    //NPMU
                    var npmulist = ddetails.Where(x => x.p_state_name == "NPMU (Delhi)").ToList();
                    int npmuttotal = npmulist.Count();
                    int npmumtotal = npmulist.Where(x => x.p_gender == "Male").Count();
                    int npmuftotal = npmulist.Where(x => x.p_gender == "Female").Count();
                    int npmutratotal = npmulist.Where(x => x.p_gender == "Transgender").Count();
                    //state
                    var spmulist = ddetails.Where(x => x.nodal == "State Level Nodal Officer").ToList();
                    int spmuttotal = spmulist.Count();
                    int spmumtotal = spmulist.Where(x => x.p_gender == "Male").Count();
                    int spmuftotal = spmulist.Where(x => x.p_gender == "Female").Count();
                    int spmutratotal = spmulist.Where(x => x.p_gender == "Transgender").Count();
                    //district

                    var dpmulist = ddetails.Where(x => x.nodal == "District Level Nodal Officer").ToList();
                    int dpmuttotal = dpmulist.Count();
                    int dpmumtotal = dpmulist.Where(x => x.p_gender == "Male").Count();
                    int dpmuftotal = dpmulist.Where(x => x.p_gender == "Female").Count();
                    int dpmutratotal = dpmulist.Where(x => x.p_gender == "Transgender").Count();
                    //block
                    var blocklist = ddetails.Where(x => x.nodal == "Block Level Nodal Officer").ToList();
                    int blockttotal = blocklist.Count();
                    int blockmtotal = blocklist.Where(x => x.p_gender == "Male").Count();
                    int blockftotal = blocklist.Where(x => x.p_gender == "Female").Count();
                    int blocktratotal = blocklist.Where(x => x.p_gender == "Transgender").Count();


                    count.sta = sta;
                    count.dis = dis;
                    count.blo = blo;
                    count.npmu = npmu;

                    count.count = fintotal;
                    count.totalcount = ttotal;
                    count.totalcount_male = mtotal;
                    count.totalcount_female = ftotal;
                    count.totalcount_trangender = tratotal;

                    count.npmucount = npmuttotal;
                    count.npmucount_male = npmumtotal;
                    count.npmucount_female = npmuftotal;
                    count.npmucount_trangender = npmutratotal;

                    count.spmucount = spmuttotal;
                    count.spmucount_male = spmumtotal;
                    count.spmucount_female = spmuftotal;
                    count.spmucount_trangender = spmutratotal;

                    count.dpmucount = dpmuttotal;
                    count.dpmucount_male = dpmumtotal;
                    count.dpmucount_female = dpmuftotal;
                    count.dpmucount_trangender = dpmutratotal;

                    count.blockcount = blockttotal;
                    count.blockcount_male = blockmtotal;
                    count.blockcount_female = blockftotal;
                    count.blockcount_trangender = blocktratotal;

                    var jsonresult = Json(count, JsonRequestBehavior.AllowGet);
                    jsonresult.MaxJsonLength = int.MaxValue;
                    return jsonresult;
                    //return Json(social_count + "," + Totalpagessocial, JsonRequestBehavior.AllowGet);
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);

            }

        }

