        public ActionResult Upload_current_image()
        {
            if (Session["UserId"] != null)
            {

                var Obj = new current_events();

                string unic_key = Request["unic_key"];
                int idd = Convert.ToInt32(unic_key);

                var Details = ABE.obj_current_events.Where(x => x.id == idd).ToList();


                var Full_Path = "";
                var Full_File_Names = "";

                if (Details[0].filename != null)
                {
                    Full_File_Names = Details[0].filename;
                }
                if (Details[0].filepath != null)
                {
                    Full_Path = Details[0].filepath;
                }

                HttpFileCollectionBase files = Request.Files;
                var obj = new current_events();
                string Paths = "";
                string File_Names = "";
                if (files.Count == 0)
                {
                    return Json("Upload Files", JsonRequestBehavior.AllowGet);
                }
                else
                {
                    var Data1 = Details.LastOrDefault();

                    int totalFileSizeInBytes = 0;
                    foreach (string fileName in files)
                    {
                        // Get the file
                        HttpPostedFileBase file = files[fileName];

                        // Get the file size in bytes
                        totalFileSizeInBytes += file.ContentLength;
                    }
                    if (totalFileSizeInBytes > 10485760) // 10 MiB for bytes.
                    {
                        return Json("Training Material File size must be less than 10 MB", JsonRequestBehavior.AllowGet);

                    }
                    //for (int i = 0; i < files.Count; i++)
                    //{

                    //    HttpPostedFileBase file = files[i];
                    foreach (string fileName in files)
                    {
                        // Get the file
                        HttpPostedFileBase file = files[fileName];
                        String FileExt = Path.GetExtension(file.FileName).ToUpper();
                        if (FileExt != ".PDF" && FileExt != ".DOC" && FileExt != ".DOCX" && FileExt != ".PPT" && FileExt != ".DOCM" && FileExt != ".XLS" && FileExt != ".XLSX" && FileExt != ".WORD")
                        {
                            return Json("Upload Training Material is not Valid File", JsonRequestBehavior.AllowGet);

                        }
                        string[] count = file.FileName.Split('.');
                        if (count.Length != 2)
                        {
                            return Json("Your Upload file has Double Extention, Upload proper file", JsonRequestBehavior.AllowGet);
                        }
                        string fname;
                        // Checking for Internet Explorer      


                        string name = Path.GetFileNameWithoutExtension(file.FileName);
                        string ext = Path.GetExtension(file.FileName);
                        fname = $"{name}_{Guid.NewGuid().ToString("N").Substring(0, 8)}{FileExt}";

                        string BasePath = AppDomain.CurrentDomain.BaseDirectory;
                        string path = System.IO.Path.Combine(BasePath, "Ataljalimages\\EventMaterial\\");
                        if (!Directory.Exists(path))
                        {
                            Directory.CreateDirectory(path);
                        }
                        path = path + fname;

                        file.SaveAs(path);
                        var MainPath = "/Ataljalimages/EventMaterial/" + fname;
                        Paths += MainPath + ',';
                        File_Names += fname + ',';

                    }

                    obj.id = idd;
                    Data1.filename = Full_File_Names + File_Names;
                    Data1.filepath = Full_Path + Paths;
                    ABE.Entry(Data1).State = EntityState.Modified;
                    ABE.SaveChanges();
                    return Json("Saved successfully", JsonRequestBehavior.AllowGet);

                }
            }
            else
            {
                return Json("SessionTimeOut", JsonRequestBehavior.AllowGet);
            }
        }

