        public int Get_Month_Number(string month)
        {
            int month_num = 0;
            switch (month)
            {
                case "April":
                    month_num = 1;
                    break;
                case "May":
                    month_num = 2;
                    break;
                case "June":
                    month_num = 3;
                    break;
                case "July":
                    month_num = 4;
                    break;
                case "August":
                    month_num = 5;
                    break;
                case "September":
                    month_num = 6;
                    break;
                case "October":
                    month_num = 7;
                    break;
                case "November":
                    month_num = 8;
                    break;
                case "December":
                    month_num = 9;
                    break;
                case "January":
                    month_num = 10;
                    break;
                case "February":
                    month_num = 11;
                    break;
                case "March":
                    month_num = 12;
                    break;
            }
            return month_num;
        }
        public string Get_Month_Number_new(string month)
        {
            string month_num = "";
            switch (month)
            {
                case "January":
                    month_num = "April";
                    break;
                case "February":
                    month_num = "May";
                    break;
                case "March":
                    month_num = "June";
                    break;
                case "April":
                    month_num = "July";
                    break;
                case "May":
                    month_num = "August";
                    break;
                case "June":
                    month_num = "September";
                    break;
                case "July":
                    month_num = "October";
                    break;
                case "August":
                    month_num = "November";
                    break;
                case "September":
                    month_num = "December";
                    break;
                case "October":
                    month_num = "January";
                    break;
                case "November":
                    month_num = "February";
                    break;
                case "December":
                    month_num = "March";
                    break;


            }
            return month_num;
        }

