        public void ViewFile(string FileName)
        {
            string Reg_Date = FileName;
            string[] Reg_Date11 = Reg_Date.Split('/');
            var RegDate = Reg_Date11[1];
            var foldername = Reg_Date11[2];
            var one_foldername = Reg_Date11[3];
            var two_foldername = Reg_Date11[4];
            var folder_filename = Reg_Date11[5];

            var Fdrive = "F:";
            var hdrive = "H:";
            var namewebside = "ataljal.mowr.gov.in";
            var ff = "ataljalimages";

            string path = "";
            string finalFilename = Path.GetFileName(folder_filename);
            string lowerCaseExtension = Path.GetExtension(finalFilename).ToLower();
            string filenameWithoutExtension = Path.GetFileNameWithoutExtension(finalFilename);
            string filename = filenameWithoutExtension + lowerCaseExtension;

            if (FileName != null && FileName != "")
            {
                string Hfilepath = hdrive + '\\' + namewebside + '\\' + ff + '\\' + foldername + '\\' + one_foldername + '\\' + two_foldername + '\\';

                path = @Hfilepath;
                DirectoryInfo directory = new DirectoryInfo(path);
                FileInfo[] files = directory.GetFiles();
                bool fileFound = false;
                foreach (FileInfo file in files)
                {
                    if (String.Compare(file.Name, filename) == 0)
                    {
                        fileFound = true;
                        Console.WriteLine(path);
                        break;
                    }
                }
                foreach (FileInfo file in files)
                {
                    if (String.Compare(file.Name, finalFilename) == 0)
                    {
                        fileFound = true;
                        Console.WriteLine(path);
                        break;
                    }
                }

                if (!fileFound)
                {
                    string Ffilepath = Fdrive + '\\' + foldername + '\\' + one_foldername + '\\' + two_foldername + '\\';

                    path = @Ffilepath;
                    DirectoryInfo directory1 = new DirectoryInfo(path);
                    FileInfo[] files1 = directory1.GetFiles();
                    foreach (FileInfo file in files1)
                    {
                        if (String.Compare(file.Name, filename) == 0)
                        {
                            fileFound = true;
                            break;

                        }
                    }
                    foreach (FileInfo file in files1)
                    {
                        if (String.Compare(file.Name, finalFilename) == 0)
                        {
                            fileFound = true;
                            break;

                        }
                    }
                }

                if (!fileFound)
                {
                    string Hfilepathaa = hdrive + '\\' + namewebside + '\\' + ff + '\\' + foldername + '\\' + one_foldername + '\\' + two_foldername + '\\';

                    path = @Hfilepathaa;
                    DirectoryInfo directory1 = new DirectoryInfo(path);
                    FileInfo[] files1 = directory1.GetFiles();
                    foreach (FileInfo file in files1)
                    {
                        if (String.Compare(file.Name, filename) == 0)
                        {
                            fileFound = true;
                            break;

                        }
                    }
                    foreach (FileInfo file in files1)
                    {
                        if (String.Compare(file.Name, finalFilename) == 0)
                        {
                            fileFound = true;
                            break;

                        }
                    }

                }

                if (fileFound)
                {
                    Response.ContentType = "image/jpeg";
                    Response.AppendHeader("Content-Disposition", "attachment; filename=" + Path.GetFileName(filename));
                    Response.WriteFile(path + filename);
                    Response.Flush();
                    Response.End();
                }
                else
                {
                    TempData["Message"] = "File not found!";

                }

            }
            else
            {
                TempData["Message"] = "File not found!";

            }


        }

