                    var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                    var Data2 = new current_events_addnew();

                    Data2.nameofparticipent = name;
                    Data2.gendernew = gender;
                    Data2.categorynew = category;
                    Data2.mobilenonew = mobile;
                    Data2.addnewid = old_id;
                    Data2.unic_key = Data1.unic_key;

                    ABE.obj_current_events_addnew.Add(Data2);
                    ABE.SaveChanges();

                    if (Data1 != null)
                    {
                        Data1.addnewid = "1";
                        ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                        int A = ABE.SaveChanges();
                        if (A > 0)
                        {
                            return Json("Save Successfully");
                        }
                        else
                        {
                            return Json("Not Save");
                        }
                    }

                }
                catch (Exception ex)
                {
                    return Json("Unsuccessful Save");

                }
                return Json("Invalid");
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

        [HttpGet]
        public ActionResult gpfeed(string id)
        {
            try
