        public ActionResult gpfeedbacksave(List<feedback_gp> Data)
        {
            try
            {
                var Data1 = Data.AsQueryable().FirstOrDefault();
                var registration_no = Data1.regno;
                var feedid = Data1.feedid;
                var SocID = Convert.ToInt32(feedid);
                var feedlist = ABE.obj_feedback_gp.Where(x => x.feedid == feedid).SingleOrDefault();
                if (feedlist == null ) {
                    var currlist = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                    Data[0].year = currlist.year;
                    Data[0].month = currlist.month;
                    Data[0].nodal_officer = "Gram Panchyat Nodal Officer";

                    ABE.obj_feedback_gp.Add(Data[0]);
                    ABE.SaveChanges();

                    currlist.feedbackentry = "Yes";
                    ABE.Entry(currlist).State = System.Data.Entity.EntityState.Modified;
                    int A = ABE.SaveChanges();

                    return Json("Feedback Saved Successfully", JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json("You have already submitted feedback", JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception Ex)
            {
                return Json("Error", JsonRequestBehavior.AllowGet);
            }

        }

        [HttpPost]
        public ActionResult Delete_gpaddnew(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<current_events_addnew>(Data);
                    if (result.id != 0)
                    {
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_current_events_addnew.Where(x => x.id == SocID).SingleOrDefault();
                        if (Data1 != null)
                        {
                            ABE.Entry(Data1).State = EntityState.Deleted;
                            ABE.SaveChanges();
                            return Json("Deleted Successfully");

                        }
                        else
                        {
                            return Json("Error", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("No Data", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception Ex)
                {
                    return Json("Error", JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }
        [HttpPost]
        public ActionResult gpupdatedelete(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {

                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<current_events_addnew>(Data);
                    if (result.addnewid != null)
                    {
                        var SocID = Convert.ToInt32(result.addnewid);
                        var Data1 = ABE.obj_current_events.Where(x => x.id == SocID).SingleOrDefault();
                        if (Data1.feedbackentry != "Yes")
                        {
                            var d2 = ABE.obj_current_events_addnew.Where(x => x.addnewid == result.addnewid).ToList();
                            foreach (var item in d2)
                            {
                                int iddd = item.id;
                                var ddd = ABE.obj_current_events_addnew.Where(x => x.id == iddd).SingleOrDefault();
                                ABE.Entry(ddd).State = EntityState.Deleted;
                                ABE.SaveChanges();
                            }
                            if (Data1 != null)
                            {
                                Data1.nameofparticipent = null;
                                Data1.gendernew = null;
                                Data1.categorynew = null;
                                Data1.mobilenonew = null;

                                ABE.Entry(Data1).State = System.Data.Entity.EntityState.Modified;
                                int A = ABE.SaveChanges();
                                if (A > 0)
                                {
                                    return Json("Delete Successfully");
                                }
                                else
                                {
                                    return Json("Not Update");
                                }
                            }

                        }

                        else
                        {
                            return Json("You have already added feedback. First, you will delete the feedback, and then delete the entry");
                        }
                    }
                }
                catch (Exception ex)
                {
                    return Json("Unsuccessful Update");

                }
                return Json("Invalid");
            }
            else
            {
                return Json("Logout", JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        public ActionResult Delete_gpaddnew_feed(string Data)
        {
            if (Session["UserId"] != null)
            {
                try
                {
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    var result = js.Deserialize<feedback_gp>(Data);
                    if (result.id != 0)
                    {
                        var SocID = Convert.ToInt32(result.id);
                        var Data1 = ABE.obj_feedback_gp.Where(x => x.id == SocID).SingleOrDefault();
                        var iddd = Convert.ToInt32(Data1.feedid);
                        var curr = ABE.obj_current_events.Where(x => x.id == iddd).SingleOrDefault();

                        curr.feedbackentry = null;
                        ABE.Entry(curr).State = EntityState.Modified;
                        ABE.SaveChanges();
                        if (Data1 != null)
                        {
